import{_ as t,o as s,c as e,ag as n}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"科学日报 · 2026-10-20（物理）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/physics/science-daily-2026-10-20.md","filePath":"topics/physics/science-daily-2026-10-20.md"}'),c={name:"topics/physics/science-daily-2026-10-20.md"};function r(i,o,a,d,l,g){return s(),e("div",null,[...o[0]||(o[0]=[n('<h1 id="科学日报-·-2026-10-20-物理" tabindex="-1">科学日报 · 2026-10-20（物理） <a class="header-anchor" href="#科学日报-·-2026-10-20-物理" aria-label="Permalink to &quot;科学日报 · 2026-10-20（物理）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-20.md</code> — 第39期 ｜ 科学板块</p></blockquote><hr><h2 id="科学日报-2026-10-20-位移电流散粒噪声——用固态器件读出量子费舍尔信息与光子统计" tabindex="-1">科学日报 2026-10-20：位移电流散粒噪声——用固态器件读出量子费舍尔信息与光子统计 <a class="header-anchor" href="#科学日报-2026-10-20-位移电流散粒噪声——用固态器件读出量子费舍尔信息与光子统计" aria-label="Permalink to &quot;科学日报 2026-10-20：位移电流散粒噪声——用固态器件读出量子费舍尔信息与光子统计&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-20.md</code> ｜ DOI: 10.1073/pnas.2611254123</p></blockquote><ul><li>痛点：<strong>量子费舍尔信息（QFI）</strong> 界定了光学相位测量的<strong>终极精度</strong>、还能揭示多光子纠缠；但编码这份灵敏度的物理量是<strong>光子数涨落</strong>——它极难被转换成可用的<strong>电信号</strong>。</li><li>方案：理论预测——利用<strong>激子极化激元</strong>的<strong>量子几何位移电流（shift current）<strong>产生的</strong>散粒噪声</strong>做光电探测，可测光子数统计，且对纯态可<strong>推断 QFI</strong>。</li><li>关键分工（本文最漂亮的一步）：求解 <strong>Lindblad 方程</strong>得到任意初始光子态下的时变非线性光电流，结果——<strong>无论入射光处于什么量子态，积分电流只依赖平均光子数</strong>；而<strong>散粒噪声保留了光子数涨落信息</strong>，其 <strong>Fano 因子正比于光子数方差</strong>。数值计算在<strong>光学薛定谔猫态</strong>与<strong>压缩真空态</strong>上验证了这两条关系。</li><li>意义：位移电流噪声型探测器给出一个<strong>不依赖可动光载流子</strong>的<strong>固态平台</strong>，用于高精度量子光学统计测量。</li><li>洞察（对本库 <code>physics</code> / <code>quantum-physics</code>）：再次印证库内主线——<strong>&quot;极限是工具的属性&quot;</strong>。此前&quot;测不了光子数涨落&quot;并非物理禁令，而是&quot;缺少一个能把涨落转成电流的换能器&quot;；<strong>量子几何（shift current）<strong>恰好提供了这个换能通道。物理上它是一个</strong>一次求平均就丢失、看二阶矩才保留</strong>的信息分工：<strong>均值走一路、方差走另一路</strong>——与库内&quot;把缠在一起的两个量拆开再分别定价&quot;的元模式（10-20 晨报第 2 条）同构。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/physics/index.md</code> ｜ <code>topics/quantum-physics/index.md</code> ｜ 第39期 科学板块</p></blockquote><p>关键词：量子费舍尔信息、QFI、光学相位测量、终极精度、多光子纠缠、光子数涨落、光子数统计、激子极化激元、量子几何、位移电流、shift current、散粒噪声、Fano因子、光子数方差、Lindblad方程、非线性光电流、薛定谔猫态、压缩真空态、可动光载流子、固态探测平台、均值与二阶矩分工</p><p>关联：<code>topics/quantum-physics/science-daily-2026-10-10.md</code>（中性原子 99.854% 保真度纠缠门——精度极限的另一种&quot;工具绕行&quot;）、<code>topics/physics/quantum-computing-progress.md</code>、<code>topics/physics/index.md</code>（&quot;每个物理极限都是暂时的，而测量工具的发明是永恒的&quot;）、<code>topics/quantum-physics/science-daily-2026-10-08.md</code>（钍-229 核光钟闭环——测量工具定义新的极限）</p>',10)])])}const h=t(c,[["render",r]]);export{u as __pageData,h as default};
